    fn migrateToV28WithSchema(self: *Store, schema_sql: [*:0]const u8) !void {
        if (try self.schemaVersion() != 27) return Error.SqliteFailure;

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        // The ledger is additive. It deliberately performs no inference or
        // backfill from legacy profile rows: any such mapping needs a reviewed
        // migration decision during a separately write-frozen cutover.
        try self.exec(schema_sql);
        var version = try self.prepare(
            \\UPDATE app_component_migrations
            \\SET version = 28, updated_at = unixepoch()
            \\WHERE component = ? AND version = 27;
        );
        defer version.deinit();
        try version.bindText(1, migration_component);
        try version.expectDone();
        if (sqlite.sqlite3_changes(try self.handle()) != 1) {
            return Error.SqliteFailure;
        }

        try self.commit();
        committed = true;
    }

    fn validateLegacyComponentAnchorHistories(self: *Store) !void {
        var conflict = try self.prepare(
            \\SELECT 1
            \\FROM tax_profile_registration_facts
            \\GROUP BY profile_id, id
            \\HAVING COUNT(DISTINCT kind) <> 1
            \\LIMIT 1;
        );
        defer conflict.deinit();
        if (try conflict.step() == .row) {
            return Error.ComponentAnchorKindConflict;
        }
    }

    fn validateLegacyIdentityHistories(self: *Store) !void {
        var statement = try self.prepare(
            \\SELECT profile_id, tin, subject_kind
            \\FROM tax_profile_revisions
            \\ORDER BY profile_id, sequence;
        );
        defer statement.deinit();

        var previous_profile: [64]u8 = undefined;
        var previous_profile_len: usize = 0;
        var previous_tin: profile_field.Tin = undefined;
        var previous_class: LegalPersonClass = undefined;
        var have_previous = false;

        while (try statement.step() == .row) {
            const profile_id = columnText(statement.raw, 0) orelse
                return Error.InconsistentIdentityHistory;
            if (profile_id.len == 0 or profile_id.len > previous_profile.len) {
                return Error.InconsistentIdentityHistory;
            }
            const raw_tin = columnText(statement.raw, 1) orelse
                return Error.InconsistentIdentityHistory;
            const tin = profile_field.Tin.parse(raw_tin) catch
                return Error.InconsistentIdentityHistory;
            const raw_kind = columnText(statement.raw, 2) orelse
                return Error.InconsistentIdentityHistory;
            const subject_kind = parseSubjectKind(raw_kind) orelse
                return Error.InconsistentIdentityHistory;
            const class = legalPersonClassForSubjectKind(subject_kind);

            const same_profile = have_previous and std.mem.eql(
                u8,
                previous_profile[0..previous_profile_len],
                profile_id,
            );
            if (same_profile) {
                if (!previous_tin.eql(&tin) or previous_class != class) {
                    return Error.InconsistentIdentityHistory;
                }
                continue;
            }

            @memcpy(previous_profile[0..profile_id.len], profile_id);
            previous_profile_len = profile_id.len;
            previous_tin = tin;
            previous_class = class;
            have_previous = true;
        }
    }

    fn backfillIdentityAnchors(self: *Store) !void {
        var revisions = try self.prepare(
            \\SELECT r.profile_id, r.id, r.tin, r.subject_kind
            \\FROM tax_profile_revisions AS r
            \\WHERE NOT EXISTS (
            \\    SELECT 1
            \\    FROM tax_profile_revisions AS earlier
            \\    WHERE earlier.profile_id = r.profile_id
            \\      AND earlier.sequence < r.sequence
            \\)
            \\ORDER BY r.profile_id;
        );
        defer revisions.deinit();
        var insert = try self.prepare(
            \\INSERT INTO tax_profile_identity_anchors (
            \\    profile_id, sequence, jurisdiction, tax_authority,
            \\    canonical_tin, legal_person_class,
            \\    established_from_revision_id, identity_correction_id
            \\) VALUES (?, 1, 'philippines',
            \\    'bureau_of_internal_revenue', ?, ?, ?, NULL);
        );
        defer insert.deinit();

        while (try revisions.step() == .row) {
            const profile_id = columnText(revisions.raw, 0) orelse
                return Error.InconsistentIdentityHistory;
            const revision_id = columnText(revisions.raw, 1) orelse
                return Error.InconsistentIdentityHistory;
            const raw_tin = columnText(revisions.raw, 2) orelse
                return Error.InconsistentIdentityHistory;
            const tin = profile_field.Tin.parse(raw_tin) catch
                return Error.InconsistentIdentityHistory;
            const raw_kind = columnText(revisions.raw, 3) orelse
                return Error.InconsistentIdentityHistory;
            const subject_kind = parseSubjectKind(raw_kind) orelse
                return Error.InconsistentIdentityHistory;

            try insert.bindText(1, profile_id);
            try insert.bindText(2, tin.asDigits());
            try insert.bindText(
                3,
                legalPersonClassText(
                    legalPersonClassForSubjectKind(subject_kind),
                ),
            );
            try insert.bindText(4, revision_id);
            try insert.expectDone();
            try insert.reset();
        }
    }

    pub fn generateOpaqueId(self: *Store) !OpaqueId {
        var statement = try self.prepare("SELECT lower(hex(randomblob(16)));");
        defer statement.deinit();
        if (try statement.step() != .row) return Error.SqliteFailure;
        const raw = columnText(statement.raw, 0) orelse return Error.SqliteFailure;
        if (raw.len != 32) return Error.SqliteFailure;
        var id: OpaqueId = undefined;
        @memcpy(&id, raw);
        if (try statement.step() != .done) return Error.SqliteFailure;
        return id;
    }

    pub fn localOwnerId(self: *Store) !OpaqueId {
        var statement = try self.prepare(
            "SELECT id FROM tax_profile_local_owner WHERE singleton = 1;",
        );
        defer statement.deinit();
        if (try statement.step() != .row) return Error.NotFound;
        const raw = columnText(statement.raw, 0) orelse
            return Error.SqliteFailure;
        if (raw.len != 32) return Error.SqliteFailure;
        var id: OpaqueId = undefined;
        @memcpy(&id, raw);
        if (try statement.step() != .done) return Error.SqliteFailure;
        return id;
    }

    /// Generates the independent random identifier used for an exact draft
    /// workspace. Filing duplicate detection uses the canonical business key,
    /// never this random value.
    pub fn generateDraftWorkspaceId(self: *Store) !DraftWorkspaceId {
        while (true) {
            var statement = try self.prepare("SELECT randomblob(16);");
            defer statement.deinit();
            if (try statement.step() != .row) return Error.SqliteFailure;
            const workspace_id = readDraftWorkspaceId(
                statement.raw,
                0,
            ) catch continue;
            if (try statement.step() != .done) return Error.SqliteFailure;
            return workspace_id;
        }
    }

    pub fn createProfile(self: *Store, value: ProfileCreate) !void {
        try validateProfileCreate(value);
        const schema_version = try self.schemaVersion();
        const sql: []const u8 = if (schema_version >= 11)
            "INSERT INTO tax_profiles(id, status, owner_id, local_label) VALUES (?, ?, (SELECT id FROM tax_profile_local_owner WHERE singleton = 1), ?);"
        else if (schema_version >= 6)
            "INSERT INTO tax_profiles(id, status, owner_id) VALUES (?, ?, (SELECT id FROM tax_profile_local_owner WHERE singleton = 1));"
        else
            "INSERT INTO tax_profiles(id, status) VALUES (?, ?);";
        var statement = try self.prepare(sql);
        defer statement.deinit();
        try statement.bindText(1, value.id);
        try statement.bindText(2, value.status.text());
        if (schema_version >= 11) {
            try statement.bindOptionalText(3, value.label);
        }
        try statement.expectDone();
    }

    /// Production first-save path. The profile shell, first immutable Base
    /// revision, and current pointer either all commit or none do.
    pub fn createProfileWithRevision(
        self: *Store,
        profile: ProfileCreate,
        revision: RevisionWrite,
    ) !void {
        try validateProfileCreate(profile);
        try validateRevision(revision, .{});
        if (!std.mem.eql(u8, profile.id, revision.profile_id)) {
            return Error.InvalidValue;
        }
        if (revision.sequence != 1) return Error.RevisionConflict;
        if (revision.expected_current_sequence) |expected| {
            if (expected != 0) return Error.RevisionConflict;
        }

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.createProfileWithRevisionInTx(profile, revision);

        try self.commit();
        committed = true;
    }

    fn createProfileWithRevisionInTx(
        self: *Store,
        profile: ProfileCreate,
        revision: RevisionWrite,
    ) !void {
        try self.createProfileWithRevisionRowsInTx(profile, revision, .{});
    }

    /// Test-only constructor for an older schema fixture. Production code has
    /// no API that accepts retired profile-attached components.
    fn createLegacyProfileWithRevisionForMigrationTest(
        self: *Store,
        profile: ProfileCreate,
        revision: RevisionWrite,
        components: RevisionComponentsWrite,
    ) !void {
        try validateProfileCreate(profile);
        try validateRevisionWithPolicy(
            revision,
            components,
            .legacy_fixture,
        );
        if (!std.mem.eql(u8, profile.id, revision.profile_id)) {
            return Error.InvalidValue;
        }
        if (revision.sequence != 1) return Error.RevisionConflict;
        if (revision.expected_current_sequence) |expected| {
            if (expected != 0) return Error.RevisionConflict;
        }

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.createProfileWithRevisionRowsInTx(
            profile,
            revision,
            components,
        );

        try self.commit();
        committed = true;
    }

    fn createProfileWithRevisionRowsInTx(
        self: *Store,
        profile: ProfileCreate,
        revision: RevisionWrite,
        components: RevisionComponentsWrite,
    ) !void {
        // Inside the immediate transaction so a second window cannot register
        // the same taxpayer between this check and the insert. Identity
        // anchors only exist from v3, and migrations replay creates against
        // older schemas, so skip the check where the table cannot be queried.
        if (try self.schemaVersion() >= 3 and
            try self.canonicalTinIsTaken(revision.identity.tin, null))
        {
            return Error.DuplicateCanonicalTin;
        }

        const schema_version = try self.schemaVersion();
        const profile_sql: []const u8 = if (schema_version >= 11)
            "INSERT INTO tax_profiles(id, status, owner_id, local_label) VALUES (?, ?, (SELECT id FROM tax_profile_local_owner WHERE singleton = 1), ?);"
        else if (schema_version >= 6)
            "INSERT INTO tax_profiles(id, status, owner_id) VALUES (?, ?, (SELECT id FROM tax_profile_local_owner WHERE singleton = 1));"
        else
            "INSERT INTO tax_profiles(id, status) VALUES (?, ?);";
        var add_profile = try self.prepare(profile_sql);
        defer add_profile.deinit();
        try add_profile.bindText(1, profile.id);
        try add_profile.bindText(2, profile.status.text());
        if (schema_version >= 11) {
            try add_profile.bindText(
                3,
                profile.label orelse profileDefaultLabel(revision.subject),
            );
        }
        try add_profile.expectDone();

        try self.insertRevisionRows(revision, components);
        var advance = try self.prepare(
            \\UPDATE tax_profiles
            \\SET current_revision_id = ?, updated_at = unixepoch()
            \\WHERE id = ? AND current_revision_id IS NULL;
        );
        defer advance.deinit();
        try advance.bindText(1, revision.id);
        try advance.bindText(2, profile.id);
        try advance.expectDone();
        if (sqlite.sqlite3_changes(try self.handle()) != 1) {
            return Error.RevisionConflict;
        }
    }

    pub fn setProfileStatus(
        self: *Store,
        profile_id: []const u8,
        status: ProfileStatus,
    ) !void {
        try validateOpaqueText(profile_id);
        var statement = try self.prepare(
            \\UPDATE tax_profiles
            \\SET status = ?, updated_at = unixepoch()
            \\WHERE id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, status.text());
        try statement.bindText(2, profile_id);
        try statement.expectDone();
        if (sqlite.sqlite3_changes(try self.handle()) == 0) return Error.NotFound;
    }

    /// Reads mutable local metadata independently from the current immutable
    /// legal/taxpayer revision. A revision-less shell may not have a label yet.
    pub fn getProfileLabel(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
    ) !?OwnedProfileLabel {
        try validateOpaqueText(profile_id);
        var statement = try self.prepare(
            \\SELECT id, local_label
            \\FROM tax_profiles
            \\WHERE id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        if (try statement.step() == .done) return null;
        const id = try dupColumn(allocator, statement.raw, 0);
        errdefer allocator.free(id);
        return .{
            .profile_id = id,
            .label = try dupOptionalColumn(allocator, statement.raw, 1),
        };
    }

    /// Changes only the profile shell's local label. It neither appends nor
    /// rewrites an effective taxpayer revision.
    pub fn updateProfileLabel(
        self: *Store,
        value: ProfileLabelWrite,
    ) !void {
        try validateOpaqueText(value.profile_id);
        try validateProfileLabel(value.label);
        var statement = try self.prepare(
            \\UPDATE tax_profiles
            \\SET local_label = ?, updated_at = unixepoch()
            \\WHERE id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, value.label);
        try statement.bindText(2, value.profile_id);
        try statement.expectDone();
        if (sqlite.sqlite3_changes(try self.handle()) == 0) return Error.NotFound;
    }

    /// Test-only lookup for proving that a historical anchor survives an old
    /// schema migration. No production API resolves retired activity anchors.
    fn getLegacyBusinessActivityAnchorForTest(
        self: *Store,
        allocator: std.mem.Allocator,
        reference: BusinessActivityAnchorRef,
    ) !?OwnedBusinessActivityAnchor {
        try validateBusinessActivityAnchorRef(reference);
        var statement = try self.prepare(
            \\SELECT profile_id, id
            \\FROM tax_profile_business_activity_anchors
            \\WHERE profile_id = ? AND id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, reference.profile_id);
        try statement.bindText(2, reference.anchor_id);
        if (try statement.step() == .done) return null;
        const profile_id = try dupColumn(allocator, statement.raw, 0);
        errdefer allocator.free(profile_id);
        return .{
            .profile_id = profile_id,
            .anchor_id = try dupColumn(allocator, statement.raw, 1),
        };
    }

    /// Test-only lookup for historical registration-anchor migration checks.
    fn getLegacyRegistrationFactAnchorForTest(
        self: *Store,
        allocator: std.mem.Allocator,
        reference: RegistrationFactAnchorRef,
    ) !?OwnedRegistrationFactAnchor {
        try validateRegistrationFactAnchorRef(reference);
        var statement = try self.prepare(
            \\SELECT profile_id, id, kind
            \\FROM tax_profile_registration_fact_anchors
            \\WHERE profile_id = ? AND id = ? AND kind = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, reference.profile_id);
        try statement.bindText(2, reference.anchor_id);
        try statement.bindText(3, reference.kind.text());
        if (try statement.step() == .done) return null;
        const profile_id = try dupColumn(allocator, statement.raw, 0);
        errdefer allocator.free(profile_id);
        const anchor_id = try dupColumn(allocator, statement.raw, 1);
        errdefer allocator.free(anchor_id);
        const kind_text = columnText(statement.raw, 2) orelse
            return Error.SqliteFailure;
        const kind = parseRegistrationFactKind(kind_text) orelse
            return Error.SqliteFailure;
        return .{
            .profile_id = profile_id,
            .anchor_id = anchor_id,
            .kind = kind,
        };
    }

    /// Appends an immutable revision and atomically advances the profile's
    /// current pointer. `expected_current_sequence` is the caller's observed
    /// sequence number. SQLite rowids never cross this boundary.
    pub fn appendRevision(
        self: *Store,
        value: RevisionWrite,
    ) !void {
        try validateRevision(value, .{});

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.appendRevisionInTx(value);

        try self.commit();
        committed = true;
    }

    /// Test-only older-schema fixture path used to prove that the explicit
    /// compatibility reader can still export physical legacy rows.
    fn appendLegacyRevisionForMigrationTest(
        self: *Store,
        value: RevisionWrite,
        components: RevisionComponentsWrite,
    ) !void {
        try validateRevisionWithPolicy(
            value,
            components,
            .legacy_fixture,
        );
        if (components.business_activities.len == 0 and
            components.registration_facts.len == 0)
        {
            return Error.InvalidValue;
        }

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.appendRevisionRowsInTx(value, components);

        try self.commit();
        committed = true;
    }

    /// Test-only compatibility fixture path for an older consolidated Base
    /// revision. It permits fields that the current editor requires to be
    /// absent, while retaining the same validation for every supplied value.
    fn appendLegacyBaseRevisionForCompatibilityTest(
        self: *Store,
        value: RevisionWrite,
    ) !void {
        try validateRevisionWithPolicy(value, .{}, .legacy_fixture);

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.appendRevisionRowsInTx(value, .{});

        try self.commit();
        committed = true;
    }

    fn appendRevisionInTx(
        self: *Store,
        value: RevisionWrite,
    ) !void {
        try self.appendRevisionRowsInTx(value, .{});
    }

    fn appendRevisionRowsInTx(
        self: *Store,
        value: RevisionWrite,
        components: RevisionComponentsWrite,
    ) !void {
        const current = try self.currentRevisionSequence(value.profile_id);
        const observed_sequence: u32 = current orelse 0;
        if (current == null and !(try self.profileExists(value.profile_id))) {
            return Error.NotFound;
        }
        if (value.expected_current_sequence) |expected| {
            if (expected != observed_sequence) return Error.RevisionConflict;
        }
        if (observed_sequence == std.math.maxInt(u32)) {
            return Error.InvalidValue;
        }
        if (value.sequence != observed_sequence + 1) {
            return Error.RevisionConflict;
        }
        try self.validateOrdinaryIdentity(value, observed_sequence);

        try self.insertRevisionRows(value, components);

        var advance = try self.prepare(
            \\UPDATE tax_profiles
            \\SET current_revision_id = ?, updated_at = unixepoch()
            \\WHERE id = ? AND (
            \\    (? = 0 AND current_revision_id IS NULL) OR
            \\    current_revision_id = (
            \\        SELECT id
            \\        FROM tax_profile_revisions
            \\        WHERE profile_id = ? AND sequence = ?
            \\    )
            \\);
        );
        defer advance.deinit();
        try advance.bindText(1, value.id);
        try advance.bindText(2, value.profile_id);
        try advance.bindInt64(3, observed_sequence);
        try advance.bindText(4, value.profile_id);
        try advance.bindInt64(5, observed_sequence);
        try advance.expectDone();
        if (sqlite.sqlite3_changes(try self.handle()) != 1) {
            return Error.RevisionConflict;
        }
        if (try self.schemaVersion() >= 11) {
            var default_label = try self.prepare(
                \\UPDATE tax_profiles
                \\SET local_label = COALESCE(local_label, ?)
                \\WHERE id = ?;
            );
            defer default_label.deinit();
            try default_label.bindText(1, profileDefaultLabel(value.subject));
            try default_label.bindText(2, value.profile_id);
            try default_label.expectDone();
        }
    }

    /// One reviewed COR decision is one commit: the accepted profile facts
    /// and the accepted forms both land or neither does (spec §11, "Apply is
    /// one transaction").
    pub fn applyCorReview(
        self: *Store,
        revision: RevisionWrite,
        forms_tax_year: i32,
        forms: []const FormRegistrationWrite,
        forms_mode: FormSetApplyMode,
    ) !void {
        try validateRevision(revision, .{});
        try validateTaxYear(forms_tax_year);
        for (forms) |form| {
            try requireValue(form.form_code);
            try requireValue(form.form_revision);
        }

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        try self.appendRevisionInTx(revision);
        switch (forms_mode) {
            .create => try self.createFormSetInTx(
                revision.profile_id,
                forms_tax_year,
                forms,
            ),
            .update => try self.updateFormSetInTx(
                revision.profile_id,
                forms_tax_year,
                forms,
            ),
        }

        try self.commit();
        committed = true;
    }

    /// The durable COR document behind one revision, or null when the
    /// revision was recorded without one (including every pre-v10 revision).
    pub fn corDocumentIdForRevision(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
        revision_id: []const u8,
    ) !?[]u8 {
        try validateOpaqueText(profile_id);
        try validateIdText(revision_id);
        var statement = try self.prepare(
            \\SELECT cor_document_id FROM tax_profile_revisions
            \\WHERE profile_id = ? AND id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindText(2, revision_id);
        if (try statement.step() == .done) return Error.NotFound;
        if (columnText(statement.raw, 0) == null) return null;
        return try dupColumn(allocator, statement.raw, 0);
    }

    pub fn getIdentityAnchor(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
    ) !?OwnedTaxpayerIdentityAnchor {
        try validateOpaqueText(profile_id);
        var statement = try self.prepare(
            \\SELECT profile_id, sequence, jurisdiction, tax_authority,
            \\       canonical_tin, legal_person_class,
            \\       established_from_revision_id, identity_correction_id
            \\FROM tax_profile_identity_anchors
            \\WHERE profile_id = ?
            \\ORDER BY sequence DESC
            \\LIMIT 1;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        if (try statement.step() == .done) return null;
        return try readIdentityAnchor(allocator, statement.raw);
    }

    /// Finds the taxpayer whose current identity anchor already holds this
    /// canonical TIN, across every status.
    ///
    /// A TIN is issued once to one taxpayer and is never reassigned, so two
    /// profiles sharing one would make their filings, evidence, and history
    /// impossible to tell apart afterwards. Archived profiles are included
    /// deliberately: archiving is not deletion, and its filings still refer to
    /// that taxpayer.
    pub fn findProfileWithCanonicalTin(
        self: *Store,
        allocator: std.mem.Allocator,
        canonical_tin: []const u8,
        exclude_profile_id: ?[]const u8,
    ) !?OwnedCanonicalTinOwner {
        const tin = profile_field.Tin.parse(canonical_tin) catch
            return Error.InvalidValue;
        if (exclude_profile_id) |value| try validateOpaqueText(value);

        var statement = try self.prepare(
            \\SELECT anchor.profile_id, profile.status,
            \\       COALESCE(revision.taxpayer_name, revision.registered_name),
            \\       COALESCE(revision.taxpayer_name, revision.registered_name)
            \\FROM tax_profile_identity_anchors AS anchor
            \\JOIN tax_profiles AS profile ON profile.id = anchor.profile_id
            \\LEFT JOIN tax_profile_revisions AS revision
            \\  ON revision.profile_id = profile.id
            \\ AND revision.id = profile.current_revision_id
            \\WHERE anchor.canonical_tin = ?
            \\  AND anchor.sequence = (
            \\      SELECT MAX(sequence)
            \\      FROM tax_profile_identity_anchors
            \\      WHERE profile_id = anchor.profile_id
            \\  )
            \\  AND (? IS NULL OR anchor.profile_id <> ?)
            \\ORDER BY anchor.profile_id
            \\LIMIT 1;
        );
        defer statement.deinit();
        try statement.bindText(1, tin.asDigits());
        try statement.bindOptionalText(2, exclude_profile_id);
        try statement.bindOptionalText(3, exclude_profile_id);
        if (try statement.step() == .done) return null;

        const profile_id = try dupColumn(allocator, statement.raw, 0);
        errdefer allocator.free(profile_id);
        const status_text = columnText(statement.raw, 1) orelse
            return Error.SqliteFailure;
        const status = std.meta.stringToEnum(ProfileStatus, status_text) orelse
            return Error.InvalidValue;
        const profile_label = try dupOptionalColumn(allocator, statement.raw, 2);
        errdefer freeOptional(allocator, profile_label);
        const display_name = try dupOptionalColumn(allocator, statement.raw, 3);
        return .{
            .profile_id = profile_id,
            .status = status,
            .profile_label = profile_label,
            .display_name = display_name,
        };
    }

    /// Records a COR reference for a taxpayer. Attaching an updated document
    /// keeps the earlier rows: evidence is a history, not a slot.
    pub fn attachCorDocument(self: *Store, value: CorDocumentWrite) !void {
        try validateIdText(value.id);
        try validateOpaqueText(value.profile_id);
        try requireValue(value.file_path);
        try requireValue(value.file_name);
        if (value.sha256.len != 64) return Error.InvalidValue;
        for (value.sha256) |byte| {
            if (!std.ascii.isHex(byte) or std.ascii.isUpper(byte)) {
                return Error.InvalidValue;
            }
        }
        if (value.byte_size == 0) return Error.InvalidValue;
        if (value.byte_size > std.math.maxInt(i64)) return Error.InvalidValue;

        var statement = try self.prepare(
            \\INSERT INTO tax_profile_cor_documents (
            \\    id, profile_id, file_path, file_name, sha256, byte_size
            \\) VALUES (?, ?, ?, ?, ?, ?);
        );
        defer statement.deinit();
        try statement.bindText(1, value.id);
        try statement.bindText(2, value.profile_id);
        try statement.bindText(3, value.file_path);
        try statement.bindText(4, value.file_name);
        try statement.bindText(5, value.sha256);
        try statement.bindInt64(6, @intCast(value.byte_size));
        try statement.expectDone();
    }

    /// The most recently attached COR for a taxpayer, or null when none is on
    /// file.
    pub fn getLatestCorDocument(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
    ) !?OwnedCorDocument {
        try validateOpaqueText(profile_id);
        var statement = try self.prepare(
            \\SELECT id, profile_id, file_path, file_name, sha256,
            \\       byte_size, attached_at
            \\FROM tax_profile_cor_documents
            \\WHERE profile_id = ?
            \\ORDER BY attached_at DESC, rowid DESC
            \\LIMIT 1;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        if (try statement.step() == .done) return null;

        const id = try dupColumn(allocator, statement.raw, 0);
        errdefer allocator.free(id);
        const owner = try dupColumn(allocator, statement.raw, 1);
        errdefer allocator.free(owner);
        const file_path = try dupColumn(allocator, statement.raw, 2);
        errdefer allocator.free(file_path);
        const file_name = try dupColumn(allocator, statement.raw, 3);
        errdefer allocator.free(file_name);
        const digest = try dupColumn(allocator, statement.raw, 4);
        errdefer allocator.free(digest);
        const size = sqlite.sqlite3_column_int64(statement.raw, 5);
        if (size <= 0) return Error.InvalidValue;
        return .{
            .id = id,
            .profile_id = owner,
            .file_path = file_path,
            .file_name = file_name,
            .sha256 = digest,
            .byte_size = @intCast(size),
            .attached_at_unix_seconds = sqlite.sqlite3_column_int64(
                statement.raw,
                6,
            ),
        };
    }

    pub fn getIdentityAnchorAtSequence(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
        sequence: u32,
    ) !?OwnedTaxpayerIdentityAnchor {
        try validateOpaqueText(profile_id);
        if (sequence == 0) return Error.InvalidValue;
        var statement = try self.prepare(
            \\SELECT profile_id, sequence, jurisdiction, tax_authority,
            \\       canonical_tin, legal_person_class,
            \\       established_from_revision_id, identity_correction_id
            \\FROM tax_profile_identity_anchors
            \\WHERE profile_id = ? AND sequence = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindInt64(2, sequence);
        if (try statement.step() == .done) return null;
        return try readIdentityAnchor(allocator, statement.raw);
    }

    /// Records an audited correction without rewriting either the prior
    /// anchor or any profile revision. The new anchor becomes authoritative
    /// only if both rows commit.
    pub fn recordIdentityCorrection(
        self: *Store,
        value: IdentityCorrectionWrite,
    ) !u32 {
        try validateIdText(value.id);
        try validateOpaqueText(value.profile_id);
        try validateEvolutionSourceReference(value.reason);
        try validateEvolutionSourceReference(value.actor_reference);
        try validateEvolutionSourceReference(value.provenance);
        const new_tin = profile_field.Tin.parse(
            value.new_canonical_tin,
        ) catch return Error.InvalidValue;
        // Identity corrections are the audited normalization boundary. A
        // readable 9/12/13-digit legacy value may remain on its old anchor,
        // but a newly recorded correction must use the complete 3-3-3-5 TIN.
        if (new_tin.asDigits().len != 14) return Error.InvalidValue;

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        if (!(try self.profileExists(value.profile_id))) {
            return Error.NotFound;
        }
        const current = (try self.currentAnchorSnapshot(
            value.profile_id,
        )) orelse return Error.MissingIdentityAnchor;
        if (current.sequence != value.expected_anchor_sequence) {
            return Error.IdentityCorrectionConflict;
        }
        if (current.sequence == std.math.maxInt(u32)) {
            return Error.InvalidValue;
        }
        const same_tin = std.mem.eql(
            u8,
            current.canonicalTin(),
            new_tin.asDigits(),
        );
        if (same_tin and
            current.legal_person_class == value.new_legal_person_class)
        {
            return Error.NoIdentityCorrection;
        }
        // A correction may not move this taxpayer onto a TIN another taxpayer
        // already holds; that would merge two identities by side effect.
        if (!same_tin and try self.canonicalTinIsTaken(
            new_tin.asDigits(),
            value.profile_id,
        )) {
            return Error.DuplicateCanonicalTin;
        }
        const next_sequence = current.sequence + 1;

        var add_anchor = try self.prepare(
            \\INSERT INTO tax_profile_identity_anchors (
            \\    profile_id, sequence, jurisdiction, tax_authority,
            \\    canonical_tin, legal_person_class,
            \\    established_from_revision_id, identity_correction_id
            \\) VALUES (?, ?, 'philippines',
            \\    'bureau_of_internal_revenue', ?, ?, NULL, ?);
        );
        defer add_anchor.deinit();
        try add_anchor.bindText(1, value.profile_id);
        try add_anchor.bindInt64(2, next_sequence);
        try add_anchor.bindText(3, new_tin.asDigits());
        try add_anchor.bindText(
            4,
            legalPersonClassText(value.new_legal_person_class),
        );
        try add_anchor.bindText(5, value.id);
        try add_anchor.expectDone();

        var add_event = try self.prepare(
            \\INSERT INTO tax_profile_identity_corrections (
            \\    id, profile_id, old_anchor_sequence,
            \\    new_anchor_sequence, old_canonical_tin,
            \\    new_canonical_tin, old_legal_person_class,
            \\    new_legal_person_class, reason, actor_reference,
            \\    recorded_at_unix_seconds, provenance
            \\) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
        );
        defer add_event.deinit();
        try add_event.bindText(1, value.id);
        try add_event.bindText(2, value.profile_id);
        try add_event.bindInt64(3, current.sequence);
        try add_event.bindInt64(4, next_sequence);
        try add_event.bindText(5, current.canonicalTin());
        try add_event.bindText(6, new_tin.asDigits());
        try add_event.bindText(
            7,
            legalPersonClassText(current.legal_person_class),
        );
        try add_event.bindText(
            8,
            legalPersonClassText(value.new_legal_person_class),
        );
        try add_event.bindText(9, value.reason);
        try add_event.bindText(10, value.actor_reference);
        try add_event.bindInt64(11, value.recorded_at_unix_seconds);
        try add_event.bindText(12, value.provenance);
        try add_event.expectDone();

        try self.commit();
        committed = true;
        return next_sequence;
    }

    pub fn getIdentityCorrection(
        self: *Store,
        allocator: std.mem.Allocator,
        correction_id: []const u8,
    ) !?OwnedIdentityCorrection {
        try validateIdText(correction_id);
        var statement = try self.prepare(
            \\SELECT id, profile_id, old_anchor_sequence,
            \\       new_anchor_sequence, old_canonical_tin,
            \\       new_canonical_tin, old_legal_person_class,
            \\       new_legal_person_class, reason, actor_reference,
            \\       recorded_at_unix_seconds, provenance
            \\FROM tax_profile_identity_corrections
            \\WHERE id = ?;
        );
        defer statement.deinit();
        try statement.bindText(1, correction_id);
        if (try statement.step() == .done) return null;
        return try readIdentityCorrection(allocator, statement.raw);
    }

    pub fn appendCivilStatusRevision(
        self: *Store,
        value: CivilStatusRevisionWrite,
    ) !void {
        try validateOpaqueText(value.profile_id);
        if (value.sequence == 0) return Error.InvalidValue;
        try validatePeriod(value.effective);
        try validateRevisionSource(value.source);

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        if (!(try self.profileExists(value.profile_id))) return Error.NotFound;
        if ((try self.currentAnchorSnapshot(value.profile_id)) == null) {
            return Error.MissingIdentityAnchor;
        }
        const current_sequence = try self.currentCivilStatusSequence(
            value.profile_id,
        );
        if (current_sequence == std.math.maxInt(u32)) {
            return Error.InvalidValue;
        }
        if (current_sequence != value.expected_current_sequence or
            value.sequence != current_sequence + 1)
        {
            return Error.RevisionConflict;
        }
        const source_tag: RevisionSourceTag = value.source;
        const source_reference: ?[]const u8 = switch (value.source) {
            .manual_entry => null,
            .imported => |reference| reference,
            .migrated => |reference| reference,
        };
        var insert = try self.prepare(
            \\INSERT INTO tax_profile_civil_status_revisions (
            \\    profile_id, sequence, effective_from, effective_until,
            \\    status, source_tag, source_reference
            \\) VALUES (?, ?, ?, ?, ?, ?, ?);
        );
        defer insert.deinit();
        try insert.bindText(1, value.profile_id);
        try insert.bindInt64(2, value.sequence);
        try insert.bindDate(3, value.effective.from[0..]);
        try insert.bindOptionalDate(
            4,
            optionalDateSlice(&value.effective.until),
        );
        try insert.bindText(5, civilStatusText(value.status));
        try insert.bindText(6, source_tag.text());
        try insert.bindOptionalText(7, source_reference);
        try insert.expectDone();

        try self.commit();
        committed = true;
    }

    pub fn getCivilStatusAsOf(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
        effective_on: []const u8,
    ) !?OwnedCivilStatusRevision {
        try validateOpaqueText(profile_id);
        try validateDate(effective_on);
        var statement = try self.prepare(
            \\SELECT profile_id, sequence, effective_from,
            \\       effective_until, status, source_tag, source_reference
            \\FROM tax_profile_civil_status_revisions
            \\WHERE profile_id = ?
            \\  AND effective_from <= ?
            \\  AND (effective_until IS NULL OR effective_until >= ?)
            \\ORDER BY sequence DESC
            \\LIMIT 1;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindText(2, effective_on);
        try statement.bindText(3, effective_on);
        if (try statement.step() == .done) return null;
        return try readCivilStatusRevision(allocator, statement.raw);
    }

    pub fn addProfileRelationship(
        self: *Store,
        value: ProfileRelationshipWrite,
    ) !void {
        try validateIdText(value.id);
        try validateOpaqueText(value.from_profile_id);
        try validateOpaqueText(value.to_profile_id);
        if (std.mem.eql(
            u8,
            value.from_profile_id,
            value.to_profile_id,
        )) return Error.InvalidRelationship;
        try validatePeriod(value.effective);
        try validateEvolutionSourceReference(value.provenance);

        try self.beginImmediate();
        var committed = false;
        errdefer if (!committed) self.rollbackNoFail();

        if (!(try self.profileExists(value.from_profile_id)) or
            !(try self.profileExists(value.to_profile_id)))
        {
            return Error.NotFound;
        }
        const from_anchor = (try self.currentAnchorSnapshot(
            value.from_profile_id,
        )) orelse return Error.MissingIdentityAnchor;
        const to_anchor = (try self.currentAnchorSnapshot(
            value.to_profile_id,
        )) orelse return Error.MissingIdentityAnchor;
        if (!relationshipClassesValid(
            value.kind,
            from_anchor.legal_person_class,
            to_anchor.legal_person_class,
        )) return Error.InvalidRelationship;

        var insert = try self.prepare(
            \\INSERT INTO tax_profile_relationships (
            \\    id, from_profile_id, to_profile_id, kind,
            \\    effective_from, effective_until, provenance
            \\) VALUES (?, ?, ?, ?, ?, ?, ?);
        );
        defer insert.deinit();
        try insert.bindText(1, value.id);
        try insert.bindText(2, value.from_profile_id);
        try insert.bindText(3, value.to_profile_id);
        try insert.bindText(4, relationshipKindText(value.kind));
        try insert.bindDate(5, value.effective.from[0..]);
        try insert.bindOptionalDate(
            6,
            optionalDateSlice(&value.effective.until),
        );
        try insert.bindText(7, value.provenance);
        try insert.expectDone();

        try self.commit();
        committed = true;
    }

    pub fn listProfileRelationshipsAsOf(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
        effective_on: []const u8,
    ) !ProfileRelationshipList {
        try validateOpaqueText(profile_id);
        try validateDate(effective_on);
        var statement = try self.prepare(
            \\SELECT id, from_profile_id, to_profile_id, kind,
            \\       effective_from, effective_until, provenance
            \\FROM tax_profile_relationships
            \\WHERE (from_profile_id = ? OR to_profile_id = ?)
            \\  AND effective_from <= ?
            \\  AND (effective_until IS NULL OR effective_until >= ?)
            \\ORDER BY effective_from, id;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindText(2, profile_id);
        try statement.bindText(3, effective_on);
        try statement.bindText(4, effective_on);

        var items: std.ArrayList(OwnedProfileRelationship) = .empty;
        errdefer {
            for (items.items) |*item| item.deinit(allocator);
            items.deinit(allocator);
        }
        while (try statement.step() == .row) {
            const item = try readProfileRelationship(
                allocator,
                statement.raw,
            );
            errdefer {
                var owned = item;
                owned.deinit(allocator);
            }
            try items.append(allocator, item);
        }
        return .{ .items = try items.toOwnedSlice(allocator) };
    }

    fn insertRevisionRows(
        self: *Store,
        value: RevisionWrite,
        components: RevisionComponentsWrite,
    ) !void {
        const source_tag: RevisionSourceTag = value.source;
        const source_reference: ?[]const u8 = switch (value.source) {
            .manual_entry => null,
            .imported => |reference| reference,
            .migrated => |reference| reference,
        };
        // Migration tests replay writes against older schemas, so both the
        // revision and component column lists must match the open store.
        const schema_version = try self.schemaVersion();
        const link_supported = schema_version >= 10;
        const component_anchors_supported = schema_version >= 12;
        const natural_person_classification_supported = schema_version >= 13;
        const complete_profile_supported = schema_version >= 25;
        if (value.cor_document_id != null and !link_supported) {
            return Error.InvalidValue;
        }
        const sole_trade_name: ?[]const u8 = switch (value.subject) {
            .sole_proprietor => |proprietor| try soleProprietorTradeName(
                proprietor,
            ),
            else => null,
        };
        if (!natural_person_classification_supported) switch (value.subject) {
            .individual => |person| {
                if (person.classification != .classification_unknown or
                    person.trade_name != null)
                {
                    return Error.InvalidValue;
                }
            },
            .sole_proprietor => {},
            .legal_entity => |entity| {
                if (entity.trade_name != null) return Error.InvalidValue;
            },
        };
        const subject_kind: SubjectKind = if (natural_person_classification_supported) switch (value.subject) {
            .individual, .sole_proprietor => .individual,
            .legal_entity => value.subject.kind(),
        } else value.subject.kind();
        const taxpayer_name: ?[]const u8 = switch (value.subject) {
            .individual => |person| person.name,
            .sole_proprietor => |proprietor| proprietor.person.name,
            .legal_entity => null,
        };
        const registered_name: ?[]const u8 = switch (value.subject) {
            .individual => null,
            .sole_proprietor => if (natural_person_classification_supported)
                null
            else
                sole_trade_name,
            .legal_entity => |entity| entity.registered_name,
        };
        const individual: ?IndividualWrite = switch (value.subject) {
            .individual => |person| person,
            .sole_proprietor => |proprietor| proprietor.person,
            .legal_entity => null,
        };
        const natural_person_classification: ?NaturalPersonClassification =
            if (!natural_person_classification_supported)
                null
            else switch (value.subject) {
                .individual => |person| person.classification,
                .sole_proprietor => .self_employed,
                .legal_entity => null,
            };
        const trade_name: ?[]const u8 = if (!natural_person_classification_supported) null else switch (value.subject) {
            .individual => |person| person.trade_name,
            .sole_proprietor => sole_trade_name,
            .legal_entity => |entity| entity.trade_name,
        };
        const insert_sql: []const u8 = if (complete_profile_supported)
            \\INSERT INTO tax_profile_revisions (
            \\    id, profile_id, sequence, effective_from, effective_until,
            \\    source_tag, source_reference, tin, rdo_code,
            \\    registered_address, zip_code, contact_number, email_address,
            \\    subject_kind, taxpayer_name, registered_name,
            \\    date_of_birth, citizenship, foreign_tax_number,
            \\    natural_person_classification, trade_name, cor_document_id,
            \\    accounting_period_basis, fiscal_year_end_month, eopt_tier,
            \\    primary_line_of_business, consolidation_review_state
            \\) VALUES (
            \\    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
            \\    ?, ?, ?, ?, ?, ?, ?, ?
            \\);
        else if (natural_person_classification_supported)
            \\INSERT INTO tax_profile_revisions (
            \\    id, profile_id, sequence, effective_from, effective_until,
            \\    source_tag, source_reference, tin, rdo_code,
            \\    registered_address, zip_code, contact_number, email_address,
            \\    subject_kind, taxpayer_name, registered_name,
            \\    date_of_birth, citizenship, foreign_tax_number,
            \\    natural_person_classification, trade_name, cor_document_id
            \\) VALUES (
            \\    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
            \\    ?, ?, ?
            \\);
        else if (link_supported)
            \\INSERT INTO tax_profile_revisions (
            \\    id, profile_id, sequence, effective_from, effective_until,
            \\    source_tag, source_reference, tin, rdo_code,
            \\    registered_address, zip_code, contact_number, email_address,
            \\    subject_kind, taxpayer_name, registered_name,
            \\    date_of_birth, citizenship, foreign_tax_number,
            \\    cor_document_id
            \\) VALUES (
            \\    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
            \\);
        else
            \\INSERT INTO tax_profile_revisions (
            \\    id, profile_id, sequence, effective_from, effective_until,
            \\    source_tag, source_reference, tin, rdo_code,
            \\    registered_address, zip_code, contact_number, email_address,
            \\    subject_kind, taxpayer_name, registered_name,
            \\    date_of_birth, citizenship, foreign_tax_number
            \\) VALUES (
            \\    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
            \\);
        ;
        var insert = try self.prepare(insert_sql);
        defer insert.deinit();
        try insert.bindText(1, value.id);
        try insert.bindText(2, value.profile_id);
        try insert.bindInt64(3, value.sequence);
        try insert.bindDate(4, value.effective.from[0..]);
        try insert.bindOptionalDate(
            5,
            optionalDateSlice(&value.effective.until),
        );
        try insert.bindText(6, source_tag.text());
        try insert.bindOptionalText(7, source_reference);
        try insert.bindText(8, value.identity.tin);
        try insert.bindText(9, value.identity.rdo_code);
        try insert.bindText(10, value.contact.registered_address);
        try insert.bindOptionalText(11, value.contact.zip_code);
        try insert.bindOptionalText(12, value.contact.contact_number);
        try insert.bindOptionalText(13, value.contact.email_address);
        try insert.bindText(14, subject_kind.text());
        try insert.bindOptionalText(15, taxpayer_name);
        try insert.bindOptionalText(16, registered_name);
        try insert.bindOptionalDate(
            17,
            if (individual) |*person|
                optionalDateSlice(&person.date_of_birth)
            else
                null,
        );
        try insert.bindOptionalText(
            18,
            if (individual) |person| person.citizenship else null,
        );
        try insert.bindOptionalText(
            19,
            if (individual) |person| person.foreign_tax_number else null,
        );
        if (natural_person_classification_supported) {
            try insert.bindOptionalText(
                20,
                if (natural_person_classification) |classification|
                    classification.text()
                else
                    null,
            );
            try insert.bindOptionalText(21, trade_name);
            try insert.bindOptionalText(22, value.cor_document_id);
            if (complete_profile_supported) {
                try insert.bindOptionalText(
                    23,
                    if (value.accounting_period_basis) |basis|
                        basis.text()
                    else
                        null,
                );
                try insert.bindOptionalInt64(
                    24,
                    if (value.fiscal_year_end_month) |month|
                        @as(i64, month)
                    else
                        null,
                );
                try insert.bindOptionalText(
                    25,
                    if (value.eopt_tier) |tier| tier.text() else null,
                );
                try insert.bindOptionalText(26, value.primary_line_of_business);
                try insert.bindText(
                    27,
                    value.consolidation_review_state.text(),
                );
            }
        } else if (link_supported) {
            try insert.bindOptionalText(20, value.cor_document_id);
        }
        try insert.expectDone();

        const add_activity_sql: []const u8 = if (component_anchors_supported)
            \\INSERT INTO tax_profile_business_activities (
            \\    profile_id, revision_id, id, anchor_id,
            \\    line_of_business, atc, effective_from,
            \\    effective_until, ordinal
            \\) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);
        else
            \\INSERT INTO tax_profile_business_activities (
            \\    profile_id, revision_id, id, line_of_business, atc,
            \\    effective_from, effective_until, ordinal
            \\) VALUES (?, ?, ?, ?, ?, ?, ?, ?);
        ;
        var add_activity = try self.prepare(add_activity_sql);
        defer add_activity.deinit();
        for (components.business_activities) |activity| {
            const anchor_id = activity.anchor_id orelse activity.id;
            if (component_anchors_supported) {
                try self.ensureBusinessActivityAnchor(
                    value.profile_id,
                    anchor_id,
                );
            }
            try add_activity.bindText(1, value.profile_id);
            try add_activity.bindText(2, value.id);
            try add_activity.bindText(3, activity.id);
            if (component_anchors_supported) {
                try add_activity.bindText(4, anchor_id);
                try add_activity.bindText(5, activity.line_of_business);
                try add_activity.bindOptionalText(6, activity.atc);
                try add_activity.bindDate(7, activity.effective.from[0..]);
                try add_activity.bindOptionalDate(
                    8,
                    optionalDateSlice(&activity.effective.until),
                );
                try add_activity.bindInt64(9, activity.ordinal);
            } else {
                try add_activity.bindText(4, activity.line_of_business);
                try add_activity.bindOptionalText(5, activity.atc);
                try add_activity.bindDate(6, activity.effective.from[0..]);
                try add_activity.bindOptionalDate(
                    7,
                    optionalDateSlice(&activity.effective.until),
                );
                try add_activity.bindInt64(8, activity.ordinal);
            }
            try add_activity.expectDone();
            try add_activity.reset();
        }

        const add_fact_sql: []const u8 = if (component_anchors_supported)
            \\INSERT INTO tax_profile_registration_facts (
            \\    profile_id, revision_id, id, anchor_id, kind,
            \\    value_text, effective_from, effective_until, ordinal
            \\) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);
        else
            \\INSERT INTO tax_profile_registration_facts (
            \\    profile_id, revision_id, id, kind, value_text,
            \\    effective_from, effective_until, ordinal
            \\) VALUES (?, ?, ?, ?, ?, ?, ?, ?);
        ;
        var add_fact = try self.prepare(add_fact_sql);
        defer add_fact.deinit();
        for (components.registration_facts) |fact| {
            const kind: RegistrationFactKind = fact.value;
            const anchor_id = fact.anchor_id orelse fact.id;
            const fact_value: []const u8 = switch (fact.value) {
                .tax_type => |text| text,
                .government_withholding_agent => |answer| answer.text(),
                .special_rate_basis => |text| text,
            };
            if (component_anchors_supported) {
                try self.ensureRegistrationFactAnchor(
                    value.profile_id,
                    anchor_id,
                    kind,
                );
            }
            try add_fact.bindText(1, value.profile_id);
            try add_fact.bindText(2, value.id);
            try add_fact.bindText(3, fact.id);
            if (component_anchors_supported) {
                try add_fact.bindText(4, anchor_id);
                try add_fact.bindText(5, kind.text());
                try add_fact.bindText(6, fact_value);
                try add_fact.bindDate(7, fact.effective.from[0..]);
                try add_fact.bindOptionalDate(
                    8,
                    optionalDateSlice(&fact.effective.until),
                );
                try add_fact.bindInt64(9, fact.ordinal);
            } else {
                try add_fact.bindText(4, kind.text());
                try add_fact.bindText(5, fact_value);
                try add_fact.bindDate(6, fact.effective.from[0..]);
                try add_fact.bindOptionalDate(
                    7,
                    optionalDateSlice(&fact.effective.until),
                );
                try add_fact.bindInt64(8, fact.ordinal);
            }
            try add_fact.expectDone();
            try add_fact.reset();
        }
    }

    fn ensureBusinessActivityAnchor(
        self: *Store,
        profile_id: []const u8,
        anchor_id: []const u8,
    ) !void {
        var statement = try self.prepare(
            \\INSERT INTO tax_profile_business_activity_anchors (
            \\    profile_id, id
            \\) VALUES (?, ?)
            \\ON CONFLICT(profile_id, id) DO NOTHING;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindText(2, anchor_id);
        try statement.expectDone();
    }

    fn ensureRegistrationFactAnchor(
        self: *Store,
        profile_id: []const u8,
        anchor_id: []const u8,
        kind: RegistrationFactKind,
    ) !void {
        var statement = try self.prepare(
            \\INSERT INTO tax_profile_registration_fact_anchors (
            \\    profile_id, id, kind
            \\) VALUES (?, ?, ?)
            \\ON CONFLICT(profile_id, id) DO NOTHING;
        );
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        try statement.bindText(2, anchor_id);
        try statement.bindText(3, kind.text());
        try statement.expectDone();
    }

    pub fn getCurrentRevision(
        self: *Store,
        allocator: std.mem.Allocator,
        profile_id: []const u8,
    ) !?OwnedProfileRevision {
        try validateOpaqueText(profile_id);
        const schema_version = try self.schemaVersion();
        const canonical_subject = schema_version >= 13;
        const sql: []const u8 = if (schema_version >= 25)
            \\SELECT r.id, r.sequence, r.profile_id, r.effective_from,
            \\       r.effective_until, r.source_tag, r.source_reference,
            \\       r.tin, r.rdo_code, r.registered_address, r.zip_code,
            \\       r.contact_number, r.email_address, r.subject_kind,
            \\       r.taxpayer_name, r.registered_name, r.date_of_birth,
            \\       r.citizenship, r.foreign_tax_number,
            \\       r.natural_person_classification, r.trade_name,
            \\       r.accounting_period_basis, r.fiscal_year_end_month,
            \\       r.eopt_tier, r.primary_line_of_business,
            \\       r.consolidation_review_state
            \\FROM tax_profiles AS p
            \\JOIN tax_profile_revisions AS r
            \\  ON r.profile_id = p.id AND r.id = p.current_revision_id
            \\WHERE p.id = ?;
        else if (canonical_subject)
            \\SELECT r.id, r.sequence, r.profile_id, r.effective_from,
            \\       r.effective_until, r.source_tag, r.source_reference,
            \\       r.tin, r.rdo_code, r.registered_address, r.zip_code,
            \\       r.contact_number, r.email_address, r.subject_kind,
            \\       r.taxpayer_name, r.registered_name, r.date_of_birth,
            \\       r.citizenship, r.foreign_tax_number,
            \\       r.natural_person_classification, r.trade_name,
            \\       NULL, NULL, NULL, NULL, 'confirmed'
            \\FROM tax_profiles AS p
            \\JOIN tax_profile_revisions AS r
            \\  ON r.profile_id = p.id AND r.id = p.current_revision_id
            \\WHERE p.id = ?;
        else
            \\SELECT r.id, r.sequence, r.profile_id, r.effective_from,
            \\       r.effective_until, r.source_tag, r.source_reference,
            \\       r.tin, r.rdo_code, r.registered_address, r.zip_code,
            \\       r.contact_number, r.email_address, r.subject_kind,
            \\       r.taxpayer_name, r.registered_name, r.date_of_birth,
            \\       r.citizenship, r.foreign_tax_number, NULL, NULL,
            \\       NULL, NULL, NULL, NULL, 'confirmed'
            \\FROM tax_profiles AS p
            \\JOIN tax_profile_revisions AS r
            \\  ON r.profile_id = p.id AND r.id = p.current_revision_id
            \\WHERE p.id = ?;
        ;
        var statement = try self.prepare(sql);
        defer statement.deinit();
        try statement.bindText(1, profile_id);
        return switch (try statement.step()) {
            .done => null,
            .row => try self.readRevision(
                allocator,
                statement.raw,
                canonical_subject,
            ),
        };
    }

