            errdefer source.deinit(allocator);
            const copied = try readDraftProvenanceValue(
                allocator,
                statement.raw,
                9,
                10,
                11,
            );
            const item: OwnedDraftProvenanceTransactionSeed = .{
                .filing_field = filing_field,
                .source_key = key,
                .source = source,
                .copied_seed_value = copied,
            };
            errdefer {
                var owned = item;
                owned.deinit(allocator);
