    const ambiguous_activities = [_]RegistrationActivityRevisionWrite{
        .{
            .anchor_id = "consulting",
            .metadata = .{
                .id = "v25-ambiguous-consulting-r1",
                .expected_component_sequence = 0,
                .effective = testPeriod("2026-01-01", null),
