        \\FROM tax_exact_draft_streams
        \\WHERE filing_business_key_digest = ?
        \\  AND filer_profile_id = ?
        \\  AND form_code = ?
        \\  AND form_revision = ?
        \\  AND period_key = ?
        \\  AND filing_intent = ?;
    );
    defer statement.deinit();
