fn testRevision(
    profile_id: []const u8,
    expected_current_sequence: u32,
    display_name: []const u8,
    effective_from: []const u8,
) RevisionWrite {
    return testRevisionWithTin(
        profile_id,
        expected_current_sequence,
        display_name,
        effective_from,
        "123456789000",
    );
}

/// A fixture for stores that hold more than one taxpayer: each needs its own
/// canonical TIN, because one TIN identifies exactly one taxpayer.
fn testRevisionWithTin(
    profile_id: []const u8,
    expected_current_sequence: u32,
    display_name: []const u8,
    effective_from: []const u8,
    tin: []const u8,
) RevisionWrite {
    return .{
        .id = switch (expected_current_sequence) {
            0 => "revision-1",
            1 => "revision-2",
            2 => "revision-3",
            else => "revision-later",
        },
        .profile_id = profile_id,
        .sequence = expected_current_sequence + 1,
        .expected_current_sequence = expected_current_sequence,
        .effective = testPeriod(effective_from, null),
        .source = .{ .imported = "test fixture" },
        .identity = .{
            .tin = tin,
            .rdo_code = "040",
        },
        .contact = .{
            .registered_address = "123 Sample Street",
            .zip_code = "1100",
            .contact_number = "+639000000000",
            .email_address = "demo@example.test",
        },
        .subject = .{ .sole_proprietor = .{
            .person = .{
                .name = display_name,
                .date_of_birth = testDate("1990-01-01"),
                .citizenship = "PH",
            },
            .trade_name = "Sample Trade",
        } },
        .accounting_period_basis = .calendar,
    };
}

fn testPeriod(
    from: []const u8,
    until: ?[]const u8,
) EffectivePeriodWrite {
    return .{
        .from = testDate(from),
        .until = if (until) |date| testDate(date) else null,
    };
}

fn testDate(value: []const u8) DateText {
    std.debug.assert(value.len == 10);
    return value[0..10].*;
}
